#include <bits/stdc++.h>
using namespace std;

int binarySearch(const vector<int>& arr, int x) {
    int l = 0, r = static_cast<int>(arr.size()) - 1;

    while (l <= r) {
        int m = l + (r - l) / 2;

        if (arr[m] == x)
            return m;
        if (arr[m] < x)
            l = m + 1;
        else
            r = m - 1;
    }

    return -1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    vector<int> a(n);
    for (int& x : a)
        cin >> x;

    sort(a.begin(), a.end());

    for (int i = n; i >= 1; --i) {
        if (n % i == 0 && binarySearch(a, i) != -1 && k % i == 0) {
            cout << k / i;
            return 0;
        }
    }

    return 0;
}

