#include <bits/stdc++.h>
using namespace std;

int binarySearch(int arr[], int l, int r, int x) {
    while (l <= r) {
        int m = l + (r - l) / 2;
        if (arr[m] == x)
            return m;
        if (arr[m] < x)
            l = m + 1;
        else
            r = m - 1;
    }
    return -1;
}

int main() {
    int n, k;
    cin >> n >> k;

    int* a = new int[n];
    for (int i = 0; i < n; i++)
        cin >> a[i];

    sort(a, a + n);

    for (int i = n; i >= 1; i--) {
        if (n % i == 0 && binarySearch(a, 0, n - 1, i) != -1 && k % i == 0) {
            cout << k / i;
            delete[] a;
            return 0;
        }
    }

    delete[] a;
    return 0;
}

